    public static function getVorherigerGesamtPlan(GesamtPlan $gesamtPlan): ?GesamtPlan
    {
        $sql = "SELECT * FROM gesamtplan WHERE jahr < {$gesamtPlan->jahr} ORDER BY jahr DESC LIMIT 1";
        return self::getGesamtPlanPerSql($sql);
    }

